contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint newMinSum1, uint newMinSum2) public payable {
        c.SetMinSum(newMinSum1); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.SetMinSum(newMinSum2); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(c.MinSum() == newMinSum1 && reverted);
    }

    receive() external payable {}
}

