pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 newMinSum1, uint256 newMinSum2) internal {
        try c.SetMinSum(newMinSum1) {} catch { return; }
        try c.Initialized() {} catch { return; }
        bool reverted;
        try c.SetMinSum(newMinSum2) { reverted = false; } catch { reverted = true; }
        assertTrue(c.MinSum() == newMinSum1 && reverted);
    }

    function testFuzz_run(uint256 newMinSum1, uint256 newMinSum2) public {
        _run(newMinSum1, newMinSum2);
    }

    receive() external payable {}
}
